<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('payments','view');
global $conn;$tenantId=(int)getCurrentTenantId();$error='';$success='';$rows=[];$q=$conn->prepare("SELECT * FROM failed_mpesa_transactions WHERE tenant_id=? ORDER BY id DESC LIMIT 300");if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$rows[]=$r;$q->close();}
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();requireModulePermission('payments','edit');$id=(int)($_POST['id']??0);$action=trim((string)($_POST['action']??''));$note=trim((string)($_POST['resolution_note']??''));if($id<=0||!in_array($action,['pending','reviewed','resolved','ignored'],true))$error='Invalid reconciliation action.';elseif($action==='resolved'&&$note==='')$error='Resolution note is required when resolving a failed transaction.';else{$uid=(int)getCurrentUserId();$s=$conn->prepare("UPDATE failed_mpesa_transactions SET retry_status=?,resolution_note=?,resolved_by=?,resolved_at=CASE WHEN ? IN ('resolved','ignored') THEN NOW() ELSE NULL END WHERE id=? AND tenant_id=?");if($s){$s->bind_param('ssisis',$action,$note,$uid,$action,$id,$tenantId);$s->execute();$success=$s->affected_rows?'Failed M-Pesa transaction reconciled.':'No matching transaction was changed.';$s->close();}else $error='Unable to update reconciliation status.';}}$pageTitle='Failed M-Pesa';require_once '../includes/header.php';?><div class="dashboard-card"><div class="page-header"><div><h2>Failed M-Pesa Transactions</h2><p>Review, reconcile and close failed collections without altering the original payment ledger.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="table-responsive"><table><thead><tr><th>Phone</th><th>Amount</th><th>Reference</th><th>Failure</th><th>Status</th><th>Created</th><th>Reconcile</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><?=e($x['phone_number']??'—')?></td><td><?=e(formatMoney($x['amount']))?></td><td><?=e($x['account_reference']??'—')?></td><td><?=e($x['failure_reason']??$x['failure_code']??'—')?></td><td><?=e($x['retry_status'])?></td><td><?=e($x['created_at'])?></td><td><form method="post" style="display:grid;gap:5px;min-width:220px"><?=csrfField()?><input type="hidden" name="id" value="<?=$x['id']?>"><select name="action"><option value="pending">Pending</option><option value="reviewed">Reviewed</option><option value="resolved">Resolved</option><option value="ignored">Ignored</option></select><input name="resolution_note" maxlength="500" placeholder="Resolution note"><button class="btn btn-secondary">Save</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No failed M-Pesa transactions recorded.</td></tr><?php endif;?></tbody></table></div></div><?php require_once '../includes/footer.php';?>